window.LOGO_RAIC_SRC = 'data:image/png;base64,';
(function() {
  function fixLogos() {
    if (!window.LOGO_RAIC_SRC) return;
    var selectors = '.landing-logo-img, .sb-logo-img, .login-logo-img, .topbar-logo-img, .informe-logo-stamp';
    var images = document.querySelectorAll(selectors);
    images.forEach(function(img) {
      img.onerror = function() {
        this.onerror = null;
        this.src = window.LOGO_RAIC_SRC;
      };
      if (img.complete && img.naturalWidth === 0) {
        img.src = window.LOGO_RAIC_SRC;
      }
    });
    // Favicon fallback
    var fav = document.querySelector('link[rel="icon"]');
    if (fav && fav.href && fav.href.indexOf('data:') !== 0) {
      fav.href = window.LOGO_RAIC_SRC;
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', fixLogos);
  } else {
    fixLogos();
  }
  window.addEventListener('load', fixLogos);
  setTimeout(fixLogos, 200);
  setTimeout(fixLogos, 1000);
})();
